#include <algorithm>
#include <array>
#include <cstdint>
#include <iostream>
#include <map>
#include <set>
#include <stdexcept>
#include <string>
#include <tuple>
#include <unordered_map>
#include <vector>
using u64=std::uint64_t;
constexpr int FRONTIER_MAX=28,CAMPAIGN_MAX=27,RADIUS=5,SOURCE_MAX=22,CAP=64;

u64 f(char g,u64 s){u64 t=s^((s<<1)|(s<<2));if(g=='t')return t;if(g=='u')return t^1;if(g=='p')return t^1^((s&1)==0?2:0);throw std::runtime_error("generator");}
std::vector<u64> next(const std::vector<u64>&v){std::vector<u64>o;o.reserve(v.size()*3);for(u64 s:v)for(char g:std::string("tup"))o.push_back(f(g,s));std::sort(o.begin(),o.end());o.erase(std::unique(o.begin(),o.end()),o.end());return o;}
bool has(const std::vector<u64>&v,u64 x){return std::binary_search(v.begin(),v.end(),x);}
unsigned fiber(const std::vector<std::vector<u64>>&l,int k,u64 q){unsigned m=0;for(int d=0;d<4;++d)if(has(l[k+1],4*q+unsigned(d)))m|=1u<<d;return m;}
u64 masks(const std::vector<std::vector<u64>>&l,int k,u64 x,int L){u64 z=0;for(int j=0;j<L;++j){x>>=2;z|=u64(fiber(l,k-1-j,x))<<(4*j);}return z;}
bool dominant(u64 a,u64 b,int L){for(int j=0;j<L;++j)if(((a>>(4*j))&15)&~((b>>(4*j))&15))return false;return true;}
bool sync(u64 a,u64 b,int L){for(int j=0;j<L;++j){unsigned x=(a>>(4*j))&15,y=(b>>(4*j))&15;if(y!=15&&y!=x)return false;}return true;}
int defects(u64 b,int L){int n=0;for(int j=0;j<L;++j)n+=((b>>(4*j))&15)!=15;return n;}
std::string schedule(u64 s){std::string w;for(int i=0;i<CAP;++i){u64 r=s&15;char b;if(r==7)b='u';else if(r==11)b='t';else return w;s=f(b,f('p',(s-3)>>2));w.push_back(b);}throw std::runtime_error("schedule cap");}
bool admissible(const std::string&w){return w.find("uu")==std::string::npos&&w.find("ttttt")==std::string::npos&&w.find("ututtu")==std::string::npos;}

struct Occ{int k,L,best=999;u64 x,residue,cur,shadow=0;};
struct Node{int k;u64 q,p;bool operator<(const Node&o)const{return std::tie(k,q,p)<std::tie(o.k,o.q,o.p);}};
std::vector<Occ> select(const std::vector<std::vector<u64>>&l){std::vector<Occ>all;for(int k=2;k<=CAMPAIGN_MAX;++k){std::vector<Occ>os;int maxL=0;std::vector<std::unordered_map<u64,std::vector<int>>>idx(20);for(u64 x:l[k]){if((x&3)!=3)continue;auto w=schedule(x);for(int cut=0;cut<=(int)w.size();++cut){if(w.compare(cut,6,"ututut")||!admissible(w.substr(0,cut)+"utututu"))continue;int L=cut+1;u64 mm=(u64{1}<<(2*L))-1;int i=os.size();os.push_back({k,L,999,x,x&mm,masks(l,k,x,L),0});idx[L][x&mm].push_back(i);maxL=std::max(maxL,L);}}for(u64 y:l[k-1]){u64 state=y,seq=0;int dc=0;for(int j=0;j<maxL;++j){state>>=2;unsigned m=fiber(l,k-2-j,state);seq|=u64(m)<<(4*j);dc+=m!=15;int L=j+1;u64 r=y&((u64{1}<<(2*L))-1);auto it=idx[L].find(r);if(it==idx[L].end())continue;for(int i:it->second){auto&o=os[i];if(dc>o.best||!dominant(o.cur,seq,L)||!sync(o.cur,seq,L))continue;if(dc<o.best||y<o.shadow){o.best=dc;o.shadow=y;}}}}for(auto&o:os){if(o.best==999)throw std::runtime_error("shadow failure");all.push_back(o);}}return all;}

struct RKey{unsigned cm,sm;std::array<int,4>child;bool operator<(const RKey&o)const{return std::tie(cm,sm,child)<std::tie(o.cm,o.sm,o.child);}};
class Residual{const std::vector<std::vector<u64>>&l;std::vector<std::map<RKey,int>>canon;std::map<std::tuple<int,int,u64,u64>,int>memo;public:explicit Residual(const std::vector<std::vector<u64>>&x):l(x),canon(RADIUS+1){}int id(int r,const Node&n){auto key=std::make_tuple(r,n.k,n.q,n.p);auto it=memo.find(key);if(it!=memo.end())return it->second;RKey z{fiber(l,n.k,n.q),fiber(l,n.k-1,n.p),{-1,-1,-1,-1}};if(z.sm!=15&&z.sm!=z.cm)throw std::runtime_error("non-sync node");if(r)for(int d=0;d<4;++d){Node c{n.k+1,4*n.q+unsigned(d),4*n.p+unsigned(d)};if(c.k+1>FRONTIER_MAX||!has(l[c.k],c.q)||!has(l[c.k-1],c.p))continue;unsigned cm=fiber(l,c.k,c.q),sm=fiber(l,c.k-1,c.p);if(sm==15||sm==cm)z.child[d]=id(r-1,c);}auto&mp=canon[r];auto jt=mp.find(z);int v;if(jt==mp.end()){v=mp.size();mp.emplace(z,v);}else v=jt->second;memo[key]=v;return v;}int alphabet(int r)const{return canon[r].size();}};

bool legal_child(const std::vector<std::vector<u64>>&l,const Node&n,int d,Node&c){c={n.k+1,4*n.q+unsigned(d),4*n.p+unsigned(d)};if(c.k+1>FRONTIER_MAX||!has(l[c.k],c.q)||!has(l[c.k-1],c.p))return false;unsigned cm=fiber(l,c.k,c.q),sm=fiber(l,c.k-1,c.p);return sm==15||sm==cm;}

int main(){std::vector<std::vector<u64>>l(FRONTIER_MAX+1);l[1]={1};u64 outputs=1;for(int k=2;k<=FRONTIER_MAX;++k){l[k]=next(l[k-1]);outputs+=l[k].size();}auto os=select(l);std::map<int,u64>hist;std::set<Node>all,source;for(const auto&o:os){++hist[o.best];for(int j=1;j<=o.L;++j){Node n{o.k-j,o.x>>(2*j),o.shadow>>(2*j)};all.insert(n);if(n.k<=SOURCE_MAX)source.insert(n);}}Residual r(l);std::vector<std::map<Node,int>>ids(RADIUS+1);for(int d=0;d<=RADIUS;++d)for(const auto&n:source)ids[d][n]=r.id(d,n);
std::cout<<"frontier_maximum_complexity="<<FRONTIER_MAX<<'\n'<<"campaign_maximum_complexity="<<CAMPAIGN_MAX<<'\n'<<"phase_u_outputs="<<outputs<<'\n'<<"gap_222_occurrences="<<os.size()<<'\n'<<"minimum_defect_0="<<hist[0]<<'\n'<<"minimum_defect_3="<<hist[3]<<'\n'<<"unique_source_pairs_all="<<all.size()<<'\n'<<"source_pairs_complexity_at_most_22="<<source.size()<<'\n';
for(int d=0;d<=RADIUS;++d){std::map<std::pair<int,int>,std::vector<Node>>level;std::map<int,std::vector<Node>>un;for(const auto&n:source){level[{n.k,ids[d][n]}].push_back(n);un[ids[d][n]].push_back(n);}int ls=-1,us=-1;if(d<RADIUS){ls=us=0;for(const auto&[k,v]:level){(void)k;std::set<int>z;for(const auto&n:v)z.insert(ids[d+1][n]);ls+=z.size()>1;}for(const auto&[k,v]:un){(void)k;std::set<int>z;for(const auto&n:v)z.insert(ids[d+1][n]);us+=z.size()>1;}}std::cout<<"residual_radius_"<<d<<"_alphabet="<<r.alphabet(d)<<'\n'<<"residual_radius_"<<d<<"_level_classes="<<level.size()<<'\n'<<"residual_radius_"<<d<<"_unlevelled_classes="<<un.size()<<'\n';if(d<RADIUS)std::cout<<"residual_radius_"<<d<<"_level_classes_split_next="<<ls<<'\n'<<"residual_radius_"<<d<<"_unlevelled_classes_split_next="<<us<<'\n';}
std::set<int>represented;for(const auto&n:source)represented.insert(ids[4][n]);u64 transitions=0,in_all=0,in_classes=0;std::map<int,bool>closed;std::map<std::pair<int,int>,std::set<int>>targets;for(int x:represented)closed[x]=true;for(const auto&n:source){int c=ids[4][n];for(int d=0;d<4;++d){Node child;int t=-1;if(legal_child(l,n,d,child)){++transitions;in_all+=all.count(child);t=r.id(4,child);if(represented.count(t))++in_classes;else closed[c]=false;}targets[{c,d}].insert(t);}}int nondet=0,closed_count=0;for(const auto&[k,v]:targets){(void)k;nondet+=v.size()>1;}for(const auto&[k,v]:closed){(void)k;closed_count+=v;}std::cout<<"radius_4_represented_classes="<<represented.size()<<'\n'<<"radius_4_legal_transitions="<<transitions<<'\n'<<"radius_4_concrete_children_in_source_all="<<in_all<<'\n'<<"radius_4_transition_instances_to_represented_classes="<<in_classes<<'\n'<<"radius_4_nondeterministic_class_digits="<<nondet<<'\n'<<"radius_4_closed_source_classes="<<closed_count<<'\n';
std::set<Node>one;for(const auto&n:source)if(n.k<=21)one.insert(n);auto base_one=one;for(const auto&n:base_one)for(int d=0;d<4;++d){Node c;if(legal_child(l,n,d,c))one.insert(c);}std::map<int,std::vector<Node>>one4;std::set<int>one5;for(const auto&n:one){one4[r.id(4,n)].push_back(n);one5.insert(r.id(5,n));}int one_split=0;for(const auto&[k,v]:one4){(void)k;std::set<int>z;for(const auto&n:v)z.insert(r.id(5,n));one_split+=z.size()>1;}std::cout<<"one_step_closure_base_nodes="<<base_one.size()<<'\n'<<"one_step_closure_nodes="<<one.size()<<'\n'<<"one_step_closure_radius_4_classes="<<one4.size()<<'\n'<<"one_step_closure_radius_5_classes="<<one5.size()<<'\n'<<"one_step_closure_splits="<<one_split<<'\n';
std::set<Node>deep;for(const auto&n:source)if(n.k<=18)deep.insert(n);bool changed=true;while(changed){changed=false;std::vector<Node>v(deep.begin(),deep.end());for(const auto&n:v){if(n.k>=22)continue;for(int d=0;d<4;++d){Node c;if(legal_child(l,n,d,c)&&deep.insert(c).second)changed=true;}}}std::map<int,std::vector<Node>>deep4;std::set<int>deep5,seen;for(const auto&n:deep){deep4[r.id(4,n)].push_back(n);deep5.insert(r.id(5,n));}int deep_split=0;for(const auto&[k,v]:deep4){(void)k;std::set<int>z;for(const auto&n:v)z.insert(r.id(5,n));deep_split+=z.size()>1;}int level22nodes=0,level22new=0;std::set<int>level22;for(int k=1;k<=22;++k){std::set<int>z;for(const auto&n:deep)if(n.k==k)z.insert(r.id(4,n));if(k==22){for(int x:z)level22new+=!seen.count(x);level22=z;for(const auto&n:deep)level22nodes+=n.k==22;}seen.insert(z.begin(),z.end());}std::map<std::pair<int,int>,std::set<int>>interior;for(const auto&n:deep)if(n.k<22){int c=r.id(4,n);for(int d=0;d<4;++d){Node child;int t=-1;if(legal_child(l,n,d,child))t=r.id(4,child);interior[{c,d}].insert(t);}}int interior_nondet=0;for(const auto&[k,v]:interior){(void)k;interior_nondet+=v.size()>1;}std::cout<<"deep_closure_nodes="<<deep.size()<<'\n'<<"deep_closure_radius_4_classes="<<deep4.size()<<'\n'<<"deep_closure_radius_5_classes="<<deep5.size()<<'\n'<<"deep_closure_splits="<<deep_split<<'\n'<<"deep_closure_interior_nondeterministic_class_digits="<<interior_nondet<<'\n'<<"deep_closure_complexity_22_nodes="<<level22nodes<<'\n'<<"deep_closure_complexity_22_classes="<<level22.size()<<'\n'<<"deep_closure_complexity_22_new_classes="<<level22new<<'\n';
if(outputs!=40122287||os.size()!=2989||hist[0]!=2986||hist[3]!=3||all.size()!=4320||source.size()!=744||represented.size()!=409||transitions!=1558||in_all!=413||in_classes!=493||nondet||closed_count!=59||base_one.size()!=455||one.size()!=1266||one4.size()!=603||one5.size()!=603||one_split||deep.size()!=2972||deep4.size()!=1039||deep5.size()!=1039||deep_split||interior_nondet||level22nodes!=977||level22.size()!=324||level22new!=273)throw std::runtime_error("totals");}
